function() {
  // Check dataLayer directly (NOT via DL_event_id to avoid circular reference)
  var dl = window.dataLayer || [];
  for (var i = dl.length - 1; i >= 0; i--) {
    if (dl[i] && dl[i].event_id) {
      return dl[i].event_id;
    }
  }

  // Use transaction_id as base if available
  var txnId = {{DL_transaction_id}};
  if (txnId) {
    return 'li_purchase_' + txnId;
  }

  // Fallback: Generate UUID v4
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0;
    var v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

